// Automatic coset abstractions.
// Given a subgroup H generated by some moves, label every piece by the
// H-orbit of its home position, and keep orientation on an orbit when H
// preserves it (after choosing an orientation gauge).  The gauge must also
// make the abstraction equivariant under the symmetry group, so that
// symmetry reduction can be compressed.
#pragma once
#include "symm.h"
#include <cmath>
#include <numeric>

// Regauge: X' = G^-1 X G with G = (identity, g)
inline Elem regauge(const Puzzle &pz, const Elem &X, const vector<int> &g) {
  Elem G = pz.ident();
  for (int j = 0; j < pz.N; j++) G.o[j] = ((g[j] % pz.omodAt(j)) + pz.omodAt(j)) % pz.omodAt(j);
  return pz.mul(pz.mul(pz.inv(G), X), G);
}
inline Puzzle regaugePuzzle(const Puzzle &pz, const vector<int> &g) {
  Puzzle q = pz;
  for (auto &m : q.base) m.e = regauge(pz, m.e, g);
  for (auto &m : q.moves) m.e = regauge(pz, m.e, g);
  return q;
}

struct Abstraction {
  vector<int> label;     // per position: label of the piece whose home is this position (-1: orbit ignored)
  vector<int> nlabels;   // per orbit
  vector<bool> keepOri;  // per orbit
  vector<bool> ignore;   // per orbit
  vector<int> gauge;     // per position
  vector<int> Hmoves;    // move indices in H
  vector<uint32_t> oriLabMask;  // per orbit (optional): keep orientation only for pieces with these labels
  string desc;
};

struct CosetFinder {
  const Puzzle &pz;
  const vector<Elem> &syms;
  CosetFinder(const Puzzle &p, const vector<Elem> &s) : pz(p), syms(s) {}

  // H generated by the given move indices.
  Abstraction derive(const vector<int> &Hgens, bool verbose = true) {
    Abstraction A;
    int N = pz.N, no = pz.orbits.size();
    A.Hmoves = Hgens;
    // 1. position partition under H
    vector<int> uf(N); iota(uf.begin(), uf.end(), 0);
    function<int(int)> find = [&](int x) { return uf[x] == x ? x : uf[x] = find(uf[x]); };
    for (int mi : Hgens) for (int j = 0; j < N; j++) uf[find(j)] = find(pz.moves[mi].e.p[j]);
    // identical pieces must share a label (abstraction must factor through the solved coloring)
    for (int i = 0; i < N; i++) for (int j = i + 1; j < N; j++)
      if (pz.orbitOf[i] == pz.orbitOf[j] && pz.solvedLabel[i] == pz.solvedLabel[j]) uf[find(i)] = find(j);
    A.label.assign(N, -1); A.nlabels.assign(no, 0); A.keepOri.assign(no, false); A.ignore.assign(no, false);
    for (int k = 0; k < no; k++) {
      auto &ob = pz.orbits[k];
      map<int, int> ids;
      for (int j = ob.off; j < ob.off + ob.n; j++) {
        int r = find(j);
        if (!ids.count(r)) { int id = ids.size(); ids[r] = id; }
        A.label[j] = ids[r];
      }
      A.nlabels[k] = ids.size();
    }
    // 2. gauge: condition A along H generator edges: g[m.p[j]] = g[j] + m.o[j]
    A.gauge.assign(N, 0);
    for (int k = 0; k < no; k++) {
      auto &ob = pz.orbits[k];
      if (ob.omod == 1) continue;
      int o = ob.omod;
      vector<int> g(N, -1);
      bool okA = true;
      vector<int> roots;
      for (int s = ob.off; s < ob.off + ob.n && okA; s++) {
        if (g[s] >= 0) continue;
        roots.push_back(s);
        g[s] = 0;
        vector<int> st{s};
        while (!st.empty() && okA) {
          int j = st.back(); st.pop_back();
          for (int mi : Hgens) {
            auto &m = pz.moves[mi].e;
            // forward: g[m.p[j]] = g[j] + m.o[j]   and backward from the other side
            int t = m.p[j], v = ((g[j] + m.o[j]) % o + o) % o;
            if (g[t] < 0) { g[t] = v; st.push_back(t); } else if (g[t] != v) { okA = false; break; }
            for (int q = ob.off; q < ob.off + ob.n; q++) if (m.p[q] == j) {
              int v2 = ((g[j] - m.o[q]) % o + o) % o;
              if (g[q] < 0) { g[q] = v2; st.push_back(q); } else if (g[q] != v2) { okA = false; break; }
            }
          }
        }
      }
      if (!okA) { if (verbose) printf("  orbit %s: H does not preserve orientation -> drop ori\n", ob.name.c_str()); continue; }
      // free choice per component (root): brute force for condition B
      int nr = roots.size();
      long long tot = 1; for (int i = 0; i < nr; i++) tot *= o;
      if (tot > 1000000) { if (verbose) printf("  orbit %s: too many gauge choices\n", ob.name.c_str()); continue; }
      bool found = false;
      for (long long code = 0; code < tot && !found; code++) {
        vector<int> gg(N, 0);
        long long c = code;
        vector<int> add(N, 0);
        for (int i = 0; i < nr; i++) { int a = c % o; c /= o; for (int j = ob.off; j < ob.off + ob.n; j++) if (find(j) == find(roots[i])) add[j] = a; }
        for (int j = ob.off; j < ob.off + ob.n; j++) gg[j] = (g[j] + add[j]) % o;
        // condition B for every symmetry: Si'.o constant on each label class of this orbit
        bool okB = true;
        for (auto &S : syms) {
          Elem Si = regauge(pz, pz.inv(S), gg);
          map<int, int> val;
          for (int q = ob.off; q < ob.off + ob.n && okB; q++) {
            int L = A.label[q];
            auto it = val.find(L);
            if (it == val.end()) val[L] = Si.o[q]; else if (it->second != Si.o[q]) okB = false;
          }
          if (!okB) break;
        }
        if (okB) { found = true; for (int j = ob.off; j < ob.off + ob.n; j++) A.gauge[j] = gg[j]; }
      }
      if (found) A.keepOri[k] = true;
      else if (verbose) printf("  orbit %s: no gauge makes orientation equivariant -> drop ori\n", ob.name.c_str());
    }
    // description and size
    A.desc.clear();
    for (int k = 0; k < no; k++) {
      auto &ob = pz.orbits[k];
      A.desc += ob.name + ":" + to_string(A.nlabels[k]) + "cls" + (A.keepOri[k] ? "+ori " : " ");
    }
    return A;
  }
  // number of abstract states (labels arrangement x orientations), before symmetry
  static double lfact(int n) { double r = 0; for (int i = 2; i <= n; i++) r += log((double)i); return r; }
  double abstractSize(const Abstraction &A) {
    double lg = 0;
    for (size_t k = 0; k < pz.orbits.size(); k++) {
      auto &ob = pz.orbits[k];
      if (A.ignore[k]) continue;
      vector<int> cnt(A.nlabels[k], 0);
      // multiplicity of each label among *pieces* = number of positions with that label
      // (also accounts for identical pieces in the solved state: combine with solved labels)
      map<int, int> c2;
      for (int j = ob.off; j < ob.off + ob.n; j++) c2[A.label[j]]++;
      lg += lfact(ob.n);
      for (auto &kv : c2) lg -= lfact(kv.second);
      if (A.keepOri[k]) lg += (ob.n - 1) * log((double)ob.omod);
    }
    return exp(lg);
  }
};
